// const yesterday = target.toISOString().split('T')[0];

// برای تست دستی روی دیتاست 2026 شما، یک تاریخ ثابت داخل بازه دیتاست:
//const yesterday = "2026-03-20"; // یک روز از بخش افت‌کرده (روز 61-90)

//const prevDate = new Date(yesterday);
//prevDate.setDate(prevDate.getDate() - 1);
//const dayBefore = prevDate.toISOString().split('T')[0];

const yesterday = "2026-03-24";
const dayBefore = "2026-02-01";
return { yesterday, dayBefore };

const items = $input.all();
const rawEvents = items.map(item => item.json);

// حذف رکوردهای کاملاً تکراری بر اساس ترکیب session_id + event_time + event_type
const seen = new Set();
const events = rawEvents.filter(e => {
  const key = `${e.session_id}|${e.event_time}|${e.event_type}`;
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

const { yesterday, dayBefore } = $('Calculate Date').item.json;

if (events.length === 0) {
  return {
    date: yesterday,
    dayBefore,
    dau: 0,
    total_watch_time: 0,
    avg_watch_time: 0,
    avg_session_duration: 0,
    completion_rate: 0,
    total_sessions: 0
  };
}

const uniqueUsers = new Set(events.map(e => e.user_id));
const dau = uniqueUsers.size;

const totalWatchTime = events.reduce((sum, e) => sum + (e.watch_time_minutes || 0), 0);

const uniqueSessions = new Set(events.map(e => e.session_id));
const totalSessions = uniqueSessions.size;

const avgWatchTime = dau > 0 ? totalWatchTime / dau : 0;

const avgSessionDuration = totalSessions > 0
  ? totalWatchTime / totalSessions
  : 0;

const viewingEvents = events.filter(e => ['play', 'pause', 'complete'].includes(e.event_type));
const completionRate = viewingEvents.length > 0
  ? viewingEvents.reduce((sum, e) => sum + (e.completion_percentage || 0), 0) / viewingEvents.length
  : 0;

return {
  date: yesterday,
  dayBefore,
  dau: dau,
  total_watch_time: Math.round(totalWatchTime * 100) / 100,
  avg_watch_time: Math.round(avgWatchTime * 100) / 100,
  avg_session_duration: Math.round(avgSessionDuration * 100) / 100,
  completion_rate: Math.round(completionRate * 100) / 100,
  total_sessions: totalSessions
};

const today = $('Save KPI').item.json;

const prevItems = $input.all();
const prev = prevItems.length > 0 ? prevItems[0].json : null;

function pctChange(curr, prev) {
  if (prev === null || prev === undefined || prev === 0) return null;
  return Math.round(((curr - prev) / prev) * 10000) / 100;
}

return {
  date: today.date,
  dau: today.dau,
  total_watch_time: today.total_watch_time,
  avg_watch_time: today.avg_watch_time,
  avg_session_duration: today.avg_session_duration,
  completion_rate: today.completion_rate,
  total_sessions: today.total_sessions,
  has_previous_day: prev !== null,
  prev_date: prev ? prev.date : null,
  dau_change_pct: prev ? pctChange(today.dau, prev.dau) : null,
  watch_time_change_pct: prev ? pctChange(today.total_watch_time, prev.total_watch_time) : null,
  avg_watch_time_change_pct: prev ? pctChange(today.avg_watch_time, prev.avg_watch_time) : null,
  avg_session_duration_change_pct: prev ? pctChange(today.avg_session_duration, prev.avg_session_duration) : null,
  completion_rate_change_pct: prev ? pctChange(today.completion_rate, prev.completion_rate) : null,
};

const kpiChanges = $('Calculate KPI Changes').item.json;

const todayItemsRaw = $('Get Today\'s Events').all().map(item => item.json);
const prevItemsRaw = $input.all().map(item => item.json);

function dedupe(events) {
  const seen = new Set();
  return events.filter(e => {
    const key = `${e.session_id}|${e.event_time}|${e.event_type}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

const todayEvents = dedupe(todayItemsRaw);
const prevEvents = dedupe(prevItemsRaw);

function pctChange(curr, prev) {
  if (prev === null || prev === undefined || prev === 0) return null;
  return Math.round(((curr - prev) / prev) * 10000) / 100;
}

function breakdown(field) {
  const todayMap = {};
  const prevMap = {};
  for (const e of todayEvents) {
    todayMap[e[field]] = (todayMap[e[field]] || 0) + (e.watch_time_minutes || 0);
  }
  for (const e of prevEvents) {
    prevMap[e[field]] = (prevMap[e[field]] || 0) + (e.watch_time_minutes || 0);
  }
  const allKeys = new Set([...Object.keys(todayMap), ...Object.keys(prevMap)]);
  const result = [];
  for (const key of allKeys) {
    const t = todayMap[key] || 0;
    const p = prevMap[key] || 0;
    result.push({ segment: key, today: t, previous: p, change_pct: pctChange(t, p) });
  }
  result.sort((a, b) => (a.change_pct ?? 0) - (b.change_pct ?? 0));
  return result;
}

const deviceBreakdown = breakdown('device');
const versionBreakdown = breakdown('app_version');
const categoryBreakdown = breakdown('content_category');

const mainDevice = deviceBreakdown[0];
const mainVersion = versionBreakdown[0];
const mainCategory = categoryBreakdown[0];

return {
  ...kpiChanges,
  change_percent: kpiChanges.watch_time_change_pct,
  main_device: mainDevice?.segment,
  main_device_change: mainDevice?.change_pct,
  main_app_version: mainVersion?.segment,
  main_app_version_change: mainVersion?.change_pct,
  main_category: mainCategory?.segment,
  main_category_change: mainCategory?.change_pct,
  device_breakdown: deviceBreakdown,
  version_breakdown: versionBreakdown,
  category_breakdown: categoryBreakdown,
};
